	requireServedOKJSONRPC(t, rt.Endpoint, "run.stop", map[string]any{"run_id": stopRunID, "idempotency_key": stopKey})
	requireServedControlAPIIdempotencyRows(t, rt.ReceiverStateReader, rt.Backend, "run.stop", stopKey, 1)
